 void restoreSession(boolean openAccount){if(!api.hasSession()){if(openAccount)login(false);return;}if(openAccount){begin("account","Restaurando sua conta…");}final int generation=sessionEpoch;network.submit(()->{try{JSONObject d=api.request("/api/auth/me",null);main.post(()->{if(isFinishing()||isDestroyed()||generation!=sessionEpoch||!api.hasSession())return;user=d.optJSONObject("user");loadPrivateState();if(openAccount)showAccount();else navigation();});}catch(Exception e){main.post(()->{if(isFinishing()||isDestroyed()||generation!=sessionEpoch)return;if(openAccount){login(false);notice("Entre novamente na sua conta. Confira sua conexão se estiver sem internet.");}});}});}
