 String owner(){if(user==null)return "guest";try{byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(user.optString("email").getBytes("UTF-8"));StringBuilder out=new StringBuilder();for(byte b:hash)out.append(String.format("%02x",b&255));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 void loadPrivateState(){try{String s=api.secret("cart_"+owner());cart=s.isEmpty()?new JSONArray():new JSONArray(s);String f=api.secret("favorites_"+owner());favorites.clear();if(!f.isEmpty()){JSONArray a=new JSONArray(f);for(int i=0;i<a.length();i++)favorites.add(a.getString(i));}}catch(Exception e){cart=new JSONArray();favorites.clear();}}
