 void loadCatalogCache(){try{File f=new File(getFilesDir(),"public-catalog.json");String s=f.exists()?NativeStore.read(new FileInputStream(f),3*1024*1024):NativeStore.read(getAssets().open("catalog.json"),3*1024*1024);catalog=new JSONArray(s);}catch(Exception ignored){}}
 void checkAppUpdate(){
  if(paymentBusy)return;
  toast("Verificando atualizações…");
  network.submit(()->{
   JSONObject version=null;Exception failure=null;
   try{
    javax.net.ssl.HttpsURLConnection connection=(javax.net.ssl.HttpsURLConnection)new URL(NativeStore.ORIGIN+"/api/app/version").openConnection();
    connection.setConnectTimeout(10000);connection.setReadTimeout(12000);connection.setRequestProperty("Accept","application/json");connection.setRequestProperty("Cache-Control","no-cache");
    try{if(connection.getResponseCode()!=200)throw new IOException("Versão indisponível.");version=new JSONObject(NativeStore.read(connection.getInputStream(),16384));}
    finally{connection.disconnect();}
   }catch(Exception e){failure=e;}
   final JSONObject found=version;final Exception error=failure;
   main.post(()->{
    if(isFinishing()||isDestroyed())return;
    if(error!=null||found==null){toast("Não foi possível consultar a versão. Atualizando catálogo.");refreshCurrentScreen();return;}
    int installed=0;
    try{installed=getPackageManager().getPackageInfo(getPackageName(),0).versionCode;}catch(Exception ignored){}
    final String download=found.optString("download");
    final int remote=found.optInt("versionCode",-1);
    if(remote>installed&&download.equals("/api/app/download")){
     new AlertDialog.Builder(this).setTitle("Atualização Valenza disponível")
      .setMessage("Nova versão "+found.optString("version")+" disponível. O Android solicitará sua confirmação para instalar. Sua conta e seus pedidos serão preservados.")
      .setPositiveButton("Baixar atualização",(dialog,which)->external(NativeStore.ORIGIN+download))
      .setNegativeButton("Agora não",(dialog,which)->refreshCurrentScreen()).show();
    }else{toast("Aplicativo atualizado. Sincronizando dados da loja.");refreshCurrentScreen();}
   });
  });
 }
