 void orderDetail(JSONObject o){begin("order","Seu pedido");backButton(()->showOrders());page.addView(text("Pedido "+o.optString("order_number",o.optString("id")),19,WINE));page.addView(text(o.optString("status"),20,INK));JSONArray its=o.optJSONArray("items");if(its!=null)for(int i=0;i<its.length();i++){JSONObject p=its.optJSONObject(i);page.addView(text(p.optInt("quantity")+" × "+p.optString("name")+" — "+money(p.optDouble("unit_price")),15,INK));}page.addView(title(money(o.optDouble("total"))));String tracking=o.optString("tracking_code");if(!tracking.isEmpty()){page.addView(text("Rastreio: "+tracking+"\n"+o.optString("tracking_status_label"),16,INK));if(!o.optString("tracking_url").isEmpty())page.addView(button("Acompanhar entrega",()->external(o.optString("tracking_url"))));}JSONObject payment=o.optJSONObject("payment");String status=o.optString("status").toLowerCase(new Locale("pt","BR"));boolean pending=!(status.contains("pago")||status.contains("cancel")||status.contains("entreg")||status.contains("enviad")||status.contains("expir"));if(pending&&payment!=null&&payment.optString("method").equalsIgnoreCase("pix"))page.addView(button("Ver Pix deste pedido",()->recoverPix(o.optString("id"))));if(pending)page.addView(secondary("Cancelar pedido pendente",()->new AlertDialog.Builder(this).setTitle("Cancelar este pedido?").setMessage("O sistema só permite cancelar pedidos que ainda podem ser cancelados.").setPositiveButton("Cancelar pedido",(d,n)->call("/api/account/order/cancel",j("orderId",o.optString("id")),r->{clearPending(o.optString("id"),false);showOrders();})).setNegativeButton("Voltar",null).show()));page.addView(secondary("Atualizar situação",()->showOrders()));}
 void checkout(){begin("checkout","Entrega e pagamento");backButton(()->showCart());page.addView(text("Produtos: "+money(subtotal(false))+"\nNo Pix: "+money(subtotal(true)),19,WINE));page.addView(text("Sob encomenda · preparação em até 10 dias úteis, mais o prazo de transporte.",13,MUTED));JSONObject saved=new JSONObject();JSONArray addresses=account==null?null:account.optJSONArray("addresses");if(addresses!=null&&addresses.length()>0)saved=addresses.optJSONObject(0);EditText cpf=field(page,"CPF",user.optString("cpf"),2),phone=field(page,"WhatsApp",user.optString("phone"),3),birth=field(page,"Nascimento (AAAA-MM-DD)",user.optString("birthDate"),1),cep=field(page,"CEP",saved.optString("cep"),2),street=field(page,"Rua / avenida",saved.optString("street"),1),number=field(page,"Número",saved.optString("number"),1),complement=field(page,"Complemento",saved.optString("complement"),1),neighborhood=field(page,"Bairro",saved.optString("neighborhood"),1),city=field(page,"Cidade",saved.optString("city"),1),state=field(page,"UF",saved.optString("state"),1);LinearLayout freight=panel();page.addView(button("Calcular opções de entrega",()->{shipping=null;call("/api/frete",j("cep",digits(val(cep)),"produtos",items()),d->{freight.removeAllViews();JSONArray arr=d.optJSONArray("fretes");if(arr==null||arr.length()==0){freight.addView(text("Nenhuma opção disponível para este CEP.",14,MUTED));return;}for(int i=0;i<arr.length();i++){JSONObject f=arr.optJSONObject(i);freight.addView(secondary(f.optString("name")+" · "+money(f.optDouble("price"))+"\nTransporte: "+f.optInt("delivery_time")+" dias úteis após postagem",()->{shipping=j("id",f.optString("id"),"name",f.optString("name"),"carrier",f.optString("carrier",f.optString("name")),"price",f.optDouble("price"),"delivery_time",f.optInt("delivery_time"),"cep",digits(val(cep)));toast("Entrega selecionada: "+f.optString("name"));}));}});}));page.addView(freight);TextWatcher invalidate=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){shipping=null;freight.removeAllViews();}public void afterTextChanged(Editable e){}};cep.addTextChangedListener(invalidate);
  page.addView(button("Revisar e pagar com Pix",()->{if(shipping==null||!shipping.optString("cep").equals(digits(val(cep)))){notice("Calcule e selecione a entrega antes de continuar.");return;}if(digits(val(cpf)).length()!=11||digits(val(phone)).length()<10||val(street).isEmpty()||val(number).isEmpty()||val(neighborhood).isEmpty()||val(city).isEmpty()||val(state).length()!=2){notice("Preencha CPF, WhatsApp e endereço completo.");return;}try{JSONObject chosen=new JSONObject(shipping.toString());chosen.put("street",val(street));chosen.put("number",val(number));chosen.put("complement",val(complement));chosen.put("neighborhood",val(neighborhood));chosen.put("city",val(city));chosen.put("state",val(state).toUpperCase());chosen.put("cityState",val(city)+" - "+val(state).toUpperCase());JSONObject payload=j("paymentMethod","pix","name",user.optString("name"),"email",user.optString("email"),"cpf",digits(val(cpf)),"phone",digits(val(phone)),"birthDate",val(birth),"items",items(),"shipping",chosen,"total",Math.round((subtotal(true)+chosen.optDouble("price"))*100)/100.0);double total=payload.optDouble("total");new AlertDialog.Builder(this).setTitle("Confirmar pedido Pix").setMessage("Produtos com desconto Pix: "+money(subtotal(true))+"\nEntrega: "+money(chosen.optDouble("price"))+"\nTotal: "+money(total)+"\n\n"+itemsSummary()+"\n"+val(street)+", "+val(number)+" — "+val(city)+"/"+val(state)).setPositiveButton("Gerar Pix",(d,n)->createPix(payload)).setNegativeButton("Revisar",null).show();}catch(Exception e){notice("Confira os dados da entrega.");}}));
  page.addView(secondary("Pagar com cartão no checkout seguro",()->{if(paymentBusy){toast("Aguarde a resposta do pagamento.");return;}if(requireLogin())call("/api/app/checkout-session",j("items",items()),d->{external(d.getString("url"));notice("O checkout de cartão abriu no navegador seguro. Depois, acompanhe o resultado em Meus pedidos no app.");});}));page.addView(text("O cartão é processado no checkout seguro da loja, no navegador. O app não coleta os dados do seu cartão.",12,MUTED));}
 String itemsSummary(){StringBuilder s=new StringBuilder();JSONArray a=items();for(int i=0;i<a.length();i++){JSONObject it=a.optJSONObject(i);s.append(it.optInt("qty")).append(" × ").append(it.optString("name")).append("\n");}return s.toString();}
 void createPix(JSONObject payload){if(paymentBusy)return;String pending=api.secret("pending_"+owner());if(!pending.isEmpty()){new AlertDialog.Builder(this).setTitle("Você tem um Pix para conferir").setMessage("Confira o pedido anterior antes de gerar outra cobrança.").setPositiveButton("Ver meus pedidos",(d,n)->showOrders()).setNegativeButton("Voltar",null).show();return;}paymentBusy=true;Button wait=button("Gerando seu Pix…",()->{});wait.setEnabled(false);page.addView(wait);network.submit(()->{JSONObject result=null;Exception error=null;try{result=api.request("/api/pagamento?v=2",payload);}catch(Exception e){error=e;}final JSONObject d=result;final Exception ex=error;main.post(()->{if(isFinishing()||isDestroyed())return;paymentBusy=false;wait.setVisibility(View.GONE);if(ex!=null){if(ex instanceof NativeStore.ApiError&&((NativeStore.ApiError)ex).status<500&&((NativeStore.ApiError)ex).status!=408){notice(ex.getMessage());return;}notice("Não foi possível confirmar a resposta do Pix. Confira Meus pedidos antes de tentar novamente, pois o pedido pode ter sido criado.\n\n"+ex.getMessage());showOrders();return;}String id=d.optString("orderId",d.optString("paymentId"));api.secret("pending_"+owner(),id);api.secret("pending_cart_"+owner(),cart.toString());showPix(d,id);});});}
 void recoverPix(String id){call("/api/account/order/pix",j("orderId",id),d->showPix(d,id));}
 void showPix(JSONObject d,String id){if(d.optBoolean("paid")){paid(id);return;}begin("pix","Seu pagamento Pix");pixId=id;page.addView(text("Pedido "+id,12,MUTED));page.addView(text("Valor a pagar: "+money(d.optDouble("amount")),24,WINE));String b64=d.optString("qrCodeBase64"),code=d.optString("qrCode");if(!b64.isEmpty())try{byte[] bytes=android.util.Base64.decode(b64.replaceFirst("^data:image/[^;]+;base64,",""),android.util.Base64.DEFAULT);Bitmap qr=BitmapFactory.decodeByteArray(bytes,0,bytes.length);ImageView image=new ImageView(this);image.setContentDescription("QR Code Pix");image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setImageBitmap(qr);page.addView(image,new LinearLayout.LayoutParams(-1,dp(245)));}catch(Exception ignored){}if(!code.isEmpty())page.addView(button("Copiar código Pix",()->{android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);c.setPrimaryClip(ClipData.newPlainText("Pix Valenza",code));toast("Código Pix copiado.");}));else page.addView(text("O código ainda não carregou. Recupere este Pix em Meus pedidos; não gere outro.",16,INK));page.addView(text("Pague pelo aplicativo do seu banco. A confirmação aparece depois da aprovação do pagamento.",14,MUTED));page.addView(secondary("Já paguei · atualizar situação",()->checkPix(id)));page.addView(secondary("Meus pedidos",()->showOrders()));pixPoll=()->{if(resumed&&screen.equals("pix")&&pixId.equals(id)){checkPix(id);main.postDelayed(pixPoll,9000);}};main.postDelayed(pixPoll,9000);}
 void checkPix(String id){final int ticket=epoch;network.submit(()->{try{JSONObject d=api.request("/api/pagamento/"+Uri.encode(id),null);main.post(()->{if(isFinishing()||isDestroyed()||ticket!=epoch)return;String st=d.optString("status");if(st.equals("approved")||st.equals("Pago"))paid(id);else if(Arrays.asList("expired","cancelled","canceled","rejected","failed").contains(st)){clearPending(id,false);notice("Situação do pagamento: "+st);showOrders();}else toast("Pagamento ainda aguardando confirmação.");});}catch(Exception ignored){}});}
 void clearPending(String id,boolean paid){if(!api.secret("pending_"+owner()).equals(id))return;try{if(paid){String raw=api.secret("pending_cart_"+owner());JSONArray bought=raw.isEmpty()?new JSONArray():new JSONArray(raw);for(int n=0;n<bought.length();n++){JSONObject item=bought.getJSONObject(n);for(int i=cart.length()-1;i>=0;i--){JSONObject current=cart.getJSONObject(i);if(!current.optString("id").equals(item.optString("id")))continue;int remaining=current.optInt("qty")-item.optInt("qty");if(remaining<=0)cart.remove(i);else current.put("qty",remaining);}}saveCart();}}catch(Exception ignored){}api.secret("pending_"+owner(),"");api.secret("pending_cart_"+owner(),"");}
 void paid(String id){clearPending(id,true);begin("paid","Pagamento confirmado ✓");page.addView(text("Recebemos a confirmação do pagamento deste pedido. Obrigada por escolher a Valenza.",19,INK));page.addView(text("Pedido "+id,13,MUTED));page.addView(button("Acompanhar meu pedido",()->showOrders()));}
 void external(String value){try{Uri u=Uri.parse(value);if(!"https".equalsIgnoreCase(u.getScheme())){notice("Link não disponível.");return;}startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){notice("Não foi possível abrir o navegador neste aparelho.");}}
 @Override public void onBackPressed(){if(screen.startsWith("admin-")){new AdminPanel(this).back();return;}if(cinema!=null){cinema.performClick();return;}if(paymentBusy){toast("Aguarde a resposta do pagamento.");return;}if(screen.equals("welcome")){super.onBackPressed();return;}if(screen.equals("home")){new AlertDialog.Builder(this).setTitle("Sair da Valenza?").setPositiveButton("Sair",(d,n)->finish()).setNegativeButton("Continuar",null).show();return;}if(screen.equals("detail")||screen.equals("favorites"))showCatalog(false);else if(screen.equals("checkout"))showCart();else if(screen.equals("pix")||screen.equals("order"))showOrders();else showCatalog(false);}
 @Override protected void onPause(){super.onPause();resumed=false;stopAudio();if(pixPoll!=null)main.removeCallbacks(pixPoll);}
 @Override protected void onResume(){super.onResume();resumed=true;if(pixPoll!=null&&screen.equals("pix")){main.removeCallbacks(pixPoll);main.postDelayed(pixPoll,3000);}}
 @Override protected void onDestroy(){super.onDestroy();stopAudio();main.removeCallbacksAndMessages(null);network.shutdownNow();images.shutdownNow();}
